import unittest

from settings import SettingsError, parse_settings


class ParseSettingsTests(unittest.TestCase):
    def test_basic_pairs(self):
        self.assertEqual({"a": "1", "b": "2"}, parse_settings("a=1\nb=2\n"))

    def test_strips_whitespace(self):
        self.assertEqual({"a": "1"}, parse_settings("   a  =  1   \n"))

    def test_ignores_blank_and_comment_lines(self):
        self.assertEqual({"a": "1"}, parse_settings("\n# note\n   # indented\na=1\n"))

    def test_later_assignment_wins(self):
        self.assertEqual({"a": "2"}, parse_settings("a=1\na=2\n"))

    def test_value_may_contain_equals(self):
        self.assertEqual({"url": "x=1&y=2"}, parse_settings("url=x=1&y=2\n"))

    def test_missing_equals_reports_line_number(self):
        with self.assertRaises(SettingsError) as caught:
            parse_settings("a=1\nbroken\n")
        self.assertIn("line 2", str(caught.exception))

    def test_inline_comment_is_not_stripped_from_value(self):
        # A '#' inside a value is data, not a comment introducer.
        self.assertEqual({"a": "1 # not a comment"}, parse_settings("a=1 # not a comment\n"))

    def test_empty_value_is_allowed(self):
        self.assertEqual({"a": ""}, parse_settings("a=\n"))

    def test_empty_key_is_an_error(self):
        with self.assertRaises(SettingsError) as caught:
            parse_settings("=1\n")
        self.assertIn("line 1", str(caught.exception))


if __name__ == "__main__":
    unittest.main()
